diff --git a/mailnews/db/mork/morkConfig.h b/mailnews/db/mork/morkConfig.h
index 01ea2ad5d98..7f646834f6b 100644
--- a/mailnews/db/mork/morkConfig.h
+++ b/mailnews/db/mork/morkConfig.h
@@ -127,8 +127,8 @@ extern void mork_assertion_signal(const char* inMessage);
 #ifdef MORK_USE_C_STDLIB
 #  define MORK_MEMCMP(src1, src2, size) memcmp(src1, src2, size)
 #  define MORK_MEMCPY(dest, src, size) memcpy(dest, src, size)
-#  define MORK_MEMMOVE(dest, src, size) memmove(dest, src, size)
-#  define MORK_MEMSET(dest, byte, size) memset(dest, byte, size)
+#  define MORK_MEMMOVE(dest, src, size) memmove((void*)dest, src, size)
+#  define MORK_MEMSET(dest, byte, size) memset((void*)dest, byte, size)
 #  if defined(MORK_WIN)
 #    define MORK_STRCPY(dest, src) wcscpy(char16ptr_t(dest), char16ptr_t(src))
 #  else
diff --git a/mailnews/mime/src/mimeenc.cpp b/mailnews/mime/src/mimeenc.cpp
index ba1745ec39f..2892e4d2312 100644
--- a/mailnews/mime/src/mimeenc.cpp
+++ b/mailnews/mime/src/mimeenc.cpp
@@ -700,7 +700,7 @@ static MimeDecoderData* mime_decoder_init(mime_encoding which,
                                           MimeClosure closure) {
   MimeDecoderData* data = PR_NEW(MimeDecoderData);
   if (!data) return 0;
-  memset(data, 0, sizeof(*data));
+  memset((void*)data, 0, sizeof(*data));
   data->encoding = which;
   data->write_buffer = output_fn;
   data->closure = closure;
diff --git a/mailnews/mime/src/mimemoz2.cpp b/mailnews/mime/src/mimemoz2.cpp
index 22926db3d19..6ef597e6fe6 100644
--- a/mailnews/mime/src/mimemoz2.cpp
+++ b/mailnews/mime/src/mimemoz2.cpp
@@ -1166,7 +1166,7 @@ MimeDisplayOptions::MimeDisplayOptions() {
   format_out = 0;  // The format out type
   url = nullptr;

-  memset(&headers, 0, sizeof(headers));
+  memset((void*)&headers, 0, sizeof(headers));
   fancy_headers_p = false;

   output_vcard_buttons_p = false;
@@ -1450,7 +1450,7 @@ extern "C" void* mime_bridge_create_display_stream(
     return 0;
   }

-  memset(stream, 0, sizeof(*stream));
+  memset((void*)stream, 0, sizeof(*stream));
   stream->name = "MIME Conversion Stream";
   stream->complete = mime_display_stream_complete;
   stream->abort = mime_display_stream_abort;
